import sailpoint.object.Application;
import sailpoint.object.Link;

boolean isTrue(Object v) {
    if (v == null) return false;
    if (v instanceof Boolean) return ((Boolean) v).booleanValue();
    return "true".equalsIgnoreCase(v.toString().trim());
}

if (isTrue(identity.getAttribute("emergencyDisable"))) {
    return Boolean.TRUE;
}

Application app = context.getObjectByName(Application.class, "HR Authoritative CSV");
Link hr = (app == null) ? null : identity.getLink(app);
if (hr == null) {
    // No HR account: keep whatever we had before
    return (oldValue == null) ? Boolean.FALSE : Boolean.valueOf(isTrue(oldValue));
}
return Boolean.valueOf(isTrue(hr.getAttribute("inactive")));
